VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.91,"Lecture eight. Stream processing. This is how events flow from producers to consumers."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":23.359,"caps":[[0.5,5.71,"A batch job reads three log files."],[5.96,12.05,"The input is bounded, so the job finishes."],[12.3,18.07,"But posts keep arriving: the data is unbounded."],[18.32,22.33,"The end never comes, so the job waits forever."]],"warp":[[0,0],[0.5,0.5],[5.96,3.6],[12.3,6.3],[18.32,9],[23.359,12]]},{"dur":21.665,"caps":[[0.5,4.67,"A daily batch run: every post waits for midnight."],[4.92,9.41,"Run every 6 hours and the wait shrinks."],[9.66,14.47,"Every hour: no post waits more than 54 minutes."],[14.72,20.57,"No windows at all: each post is handled as it arrives."]],"warp":[[0,0],[0.5,0.5],[4.92,3.9],[9.66,6.8],[14.72,9.5],[21.665,13]]},{"dur":21.757,"caps":[[0.5,6.67,"An event: mo_17 liked post 4821."],[6.92,10.85,"It carries a timestamp: when it happened."],[11.1,14.47,"It is immutable: it cannot be edited."],[14.72,19.93,"A change of mind is a new event."]],"warp":[[0,0],[0.5,0.5],[6.92,3.4],[11.1,5.8],[14.72,8.3],[21.757,11]]},{"dur":26.796,"caps":[[0.5,5.39,"A producer makes events; a consumer uses them."],[5.64,10.77,"Polling: the consumer asks again and again."],[11.02,17.11,"720 checks an hour find only 12 events."],[17.36,21.45,"Better: a messaging system pushes each event."],[21.7,24.83,"One event can go to many consumers."]],"warp":[[0,0],[0.5,0.5],[5.64,3.2],[11.02,6],[17.36,8.6],[21.7,10.9],[26.796,13]]},{"dur":26.424,"caps":[[0.5,7.71,"6 messages a second arrive, but only 4 are handled."],[7.96,11.81,"Buffer: the queue just keeps growing."],[12.06,15.19,"Drop: what does not fit is thrown away."],[15.44,18.81,"Backpressure: the producer must wait."],[19.06,25.07,"After 10 s: 20 waiting, 14 dropped, 14 held back."]],"warp":[[0,0],[0.5,0.5],[7.96,3.2],[12.06,5.8],[15.44,8.4],[19.06,10.8],[26.424,13]]},{"dur":19.899,"caps":[[0.5,4.19,"m3 and m4 wait in the broker's memory."],[4.44,7.81,"The lower broker also writes them to disk."],[8.06,11.59,"Both brokers crash: memory is wiped."],[11.84,18.09,"After the restart, only the disk copies are left."]],"warp":[[0,0],[0.5,0.5],[4.44,3.2],[8.06,5.6],[11.84,8],[19.899,11]]},{"dur":26.796,"caps":[[0.55,7.92,"m1 goes to A and B either way."],[8.17,10.82,"Then consumer B goes offline."],[11.07,15.08,"Sent directly, m2 and m3 are lost to B."],[15.33,19.42,"The broker kept them and hands them over."],[19.67,24.88,"With a broker, consumers can come and go."]],"warp":[[0,0],[0.55,1],[8.17,2.5],[11.07,4.8],[15.33,6.5],[19.67,8.8],[26.796,12]]},{"dur":20.039,"caps":[[0.77,5.26,"Load balancing: each message goes to one consumer."],[5.51,10.24,"4 messages, 4 deliveries: they share the work."],[10.49,14.18,"Fan-out: each message goes to every consumer."],[14.43,17.88,"The same 4 messages: 8 deliveries."]],"warp":[[0,0],[0.77,1.4],[5.51,3.9],[10.49,7],[14.43,9.5],[20.039,12]]},{"dur":28.282,"caps":[[0.66,5.07,"m1 goes to Consumer 2, m2 to Consumer 1."],[5.32,7.89,"Each sends an ack when it is done."],[8.14,11.19,"Then m3 and m4 go out."],[11.44,15.53,"Consumer 2 crashes: no ack for m3."],[15.78,19.87,"So the broker delivers m3 again."],[20.12,23.33,"Consumer 1 did m4 before m3."],[23.58,26.47,"Redelivery can change the order."]],"warp":[[0,0],[0.66,1.2],[5.32,2.6],[8.14,4.2],[11.44,5.7],[15.78,8],[20.12,10.4],[23.58,12.6],[28.282,14.5]]},{"dur":13.56,"caps":[],"warp":[[0,0],[0.5,0.9],[4.68,2],[9.26,3.1],[13.56,9]]}]};
